import { multiply } from '../utils.js'
import type { ParsedTransformOrigin } from '../transform-origin.js'

const baseMatrix = [1, 0, 0, 1, 0, 0]
const MATRIX_LENGTH = 6

export type TransformDescriptor = {
  [type: string]: number | string | number[]
}

export type TransformInput = Array<number | TransformDescriptor>

function isFiniteNumberArray(value: unknown): value is number[] {
  return (
    Array.isArray(value) &&
    value.every((item) => typeof item === 'number' && Number.isFinite(item))
  )
}

function isTransformDescriptor(value: unknown): value is TransformDescriptor {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false

  const entries = Object.values(value as Record<string, unknown>)
  if (!entries.length) return false

  return entries.every((entry) => {
    if (typeof entry === 'number') return Number.isFinite(entry)
    if (typeof entry === 'string') return true
    return isFiniteNumberArray(entry)
  })
}

export function isTransformInput(value: unknown): value is TransformInput {
  if (!Array.isArray(value)) return false
  return value.every(
    (entry) =>
      (typeof entry === 'number' && Number.isFinite(entry)) ||
      isTransformDescriptor(entry)
  )
}

function isResolvedMatrix(input: TransformInput): input is number[] {
  if (!Array.isArray(input) || input.length !== MATRIX_LENGTH) return false
  for (const value of input) {
    if (typeof value !== 'number' || !Number.isFinite(value)) return false
  }
  return true
}

function resolveTransforms(
  transforms: TransformDescriptor[],
  width: number,
  height: number
): number[] {
  let matrix = [...baseMatrix]

  // Handle CSS transforms To make it easier, we convert different transform
  // types directly to a matrix and apply it recursively to all its children.
  // Transforms are applied from right to left.
  // eslint-disable-next-line @typescript-eslint/no-shadow
  for (const transform of transforms) {
    const type = Object.keys(transform)[0]
    let v = transform[type]

    // Resolve percentages based on the element's final size.
    if (typeof v === 'string') {
      if (type === 'translateX') {
        v = (parseFloat(v) / 100) * width
      } else if (type === 'translateY') {
        v = (parseFloat(v) / 100) * height
      } else {
        throw new Error(`Invalid transform: "${type}: ${v}".`)
      }
    }

    let len = v as number

    const transformMatrix = [...baseMatrix]
    switch (type) {
      case 'translateX':
        transformMatrix[4] = len
        break
      case 'translateY':
        transformMatrix[5] = len
        break
      case 'scale':
        transformMatrix[0] = len
        transformMatrix[3] = len
        break
      case 'scaleX':
        transformMatrix[0] = len
        break
      case 'scaleY':
        transformMatrix[3] = len
        break
      case 'rotate': {
        const rad = (len * Math.PI) / 180
        const c = Math.cos(rad)
        const s = Math.sin(rad)
        transformMatrix[0] = c
        transformMatrix[1] = s
        transformMatrix[2] = -s
        transformMatrix[3] = c
        break
      }
      case 'skewX':
        transformMatrix[2] = Math.tan((len * Math.PI) / 180)
        break
      case 'skewY':
        transformMatrix[1] = Math.tan((len * Math.PI) / 180)
        break
      case 'matrix': {
        // matrix(a, b, c, d, tx, ty) — value is already an array of 6 numbers
        const m = v
        if (isFiniteNumberArray(m) && m.length === MATRIX_LENGTH) {
          transformMatrix[0] = m[0]
          transformMatrix[1] = m[1]
          transformMatrix[2] = m[2]
          transformMatrix[3] = m[3]
          transformMatrix[4] = m[4]
          transformMatrix[5] = m[5]
        }
        break
      }
    }
    matrix = multiply(transformMatrix, matrix)
  }

  return matrix
}

function resolveAndCacheTransforms(
  transforms: TransformInput,
  width: number,
  height: number
): number[] {
  if (isResolvedMatrix(transforms)) {
    return transforms
  }

  const resolved = resolveTransforms(
    transforms as TransformDescriptor[],
    width,
    height
  )
  // Keep the array identity so inheritance can share the resolved matrix.
  transforms.splice(0, transforms.length, ...resolved)
  return transforms as number[]
}

export default function transform(
  {
    left,
    top,
    width,
    height,
  }: {
    left: number
    top: number
    width: number
    height: number
  },
  transforms: TransformInput,
  isInheritingTransform: boolean,
  transformOrigin?: ParsedTransformOrigin,
  parentTransforms?: TransformInput,
  parentSize?: { width: number; height: number }
) {
  let result: number[]
  const matrix = resolveAndCacheTransforms(transforms, width, height)

  // Calculate the transform origin.
  if (isInheritingTransform) {
    result = matrix
  } else {
    const xOrigin =
      transformOrigin?.xAbsolute ??
      ((transformOrigin?.xRelative ?? 50) * width) / 100
    const yOrigin =
      transformOrigin?.yAbsolute ??
      ((transformOrigin?.yRelative ?? 50) * height) / 100

    // If this element is the transform target, we attach the origin coordinates
    // to this matrix.
    const x = left + xOrigin
    const y = top + yOrigin

    // Due to the different coordinate systems, we need to move the shape to the
    // origin first, then apply the matrix, then move it back.
    result = multiply(
      [1, 0, 0, 1, x, y],
      multiply(matrix, [1, 0, 0, 1, -x, -y])
    )

    if (parentTransforms) {
      const parentWidth = parentSize?.width ?? width
      const parentHeight = parentSize?.height ?? height
      const resolvedParent = resolveAndCacheTransforms(
        parentTransforms,
        parentWidth,
        parentHeight
      )
      result = multiply(resolvedParent, result)
    }

    transforms.splice(0, transforms.length, ...result)
  }

  return `matrix(${result.map((v) => v.toFixed(2)).join(',')})`
}
